-- Hand-written: client type lock once a document is issued (M3.3 review), generated by scripts/write-triggers.ts from src/triggers.ts.
CREATE TRIGGER `clients_type_locked` BEFORE UPDATE OF type ON `clients` WHEN NEW.type IS NOT OLD.type AND EXISTS (SELECT 1 FROM documents WHERE client_id = OLD.id AND frozen_at IS NOT NULL) BEGIN SELECT RAISE(ABORT, 'client type is locked: the client has an issued document'); END;
